'use client';

import { useId, useState } from 'react';
import './product-spotlight-hero.css';

export interface ProductSpotlightFeature {
  id: string;
  label: string;
  detail: string;
  /** Horizontal and vertical positions from 0 to 1, relative to the full image. */
  x: number;
  y: number;
}

export interface ProductSpotlightHeroProps {
  eyebrow?: string;
  title: string;
  description?: string;
  image: { src: string; alt: string };
  features: ProductSpotlightFeature[];
  action?: { label: string; href: string };
  className?: string;
}

function position(value: number) {
  return `${Math.min(1, Math.max(0, Number.isFinite(value) ? value : .5)) * 100}%`;
}

/** A product introduction with two equivalent ways to explore its details. */
export function ProductSpotlightHero({
  eyebrow,
  title,
  description,
  image,
  features,
  action,
  className = '',
}: ProductSpotlightHeroProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const selectedIndex = features.findIndex(feature => feature.id === selectedId);
  const selected = features[selectedIndex];
  const instance = useId();
  const titleId = `ac-spotlight-hero-title-${instance}`;
  const detailId = `ac-spotlight-hero-detail-${instance}`;

  return (
    <section className={`ac-product-spotlight-hero ${className}`.trim()} aria-labelledby={titleId}>
      <div className="ac-product-spotlight-layout">
      <div className="ac-product-spotlight-copy">
        {eyebrow && <p className="ac-product-spotlight-eyebrow">{eyebrow}</p>}
        <h2 id={titleId}>{title}</h2>
        {description && <p className="ac-product-spotlight-description">{description}</p>}
      </div>
      <div className="ac-product-spotlight-visual">
        <div className="ac-product-spotlight-image-area">
          <img src={image.src} alt={image.alt} />
          {features.length > 0 && <div className="ac-product-spotlight-points" role="group" aria-label="Product image feature points">
            {features.map((feature, index) => <button
              key={feature.id}
              type="button"
              className="ac-product-spotlight-point"
              style={{ left: position(feature.x), top: position(feature.y) }}
              aria-label={`Explore feature ${index + 1}: ${feature.label}`}
              aria-pressed={selectedId === feature.id}
              aria-controls={detailId}
              onClick={() => setSelectedId(feature.id)}
            ><span aria-hidden="true">{String(index + 1).padStart(2, '0')}</span></button>)}
          </div>}
        </div>
        {features.length > 0 && <div className="ac-product-spotlight-detail" id={detailId} aria-live="polite" aria-atomic="true">
          <span className="ac-product-spotlight-detail-index" aria-hidden="true">{selected ? String(selectedIndex + 1).padStart(2, '0') : '+'}</span>
          <div><strong>{selected?.label ?? 'A closer look.'}</strong><p>{selected?.detail ?? 'Choose a point on the image or a feature from the list to explore the details.'}</p></div>
        </div>}
      </div>
      <div className="ac-product-spotlight-features">
        {features.length > 0 && <ol className="ac-product-spotlight-list" aria-label="Explore the product features">
          {features.map((feature, index) => <li key={feature.id}>
            <button type="button" aria-pressed={selectedId === feature.id} aria-controls={detailId} onClick={() => setSelectedId(feature.id)}>
              <span className="ac-product-spotlight-number" aria-hidden="true">{String(index + 1).padStart(2, '0')}</span>
              <span><strong>{feature.label}</strong><span className="ac-product-spotlight-list-detail">{feature.detail}</span></span>
              <span className="ac-product-spotlight-list-arrow" aria-hidden="true">↗</span>
            </button>
          </li>)}
        </ol>}
        {action && <a className="ac-product-spotlight-action" href={action.href}>{action.label}<span aria-hidden="true">↗</span></a>}
      </div>
      </div>
    </section>
  );
}

.ac-product-spotlight-hero,
.ac-product-spotlight-hero * { box-sizing: border-box; }

.ac-product-spotlight-hero {
  --ac-spotlight-surface: #eeece4;
  --ac-spotlight-ink: #2e342d;
  --ac-spotlight-muted: #62675e;
  --ac-spotlight-line: #cdcec3;
  --ac-spotlight-accent: #d85734;
  container-type: inline-size;
  min-height: 560px;
  overflow: hidden;
  border-radius: 4px;
  background: var(--ac-spotlight-surface);
  color: var(--ac-spotlight-ink);
  font-family: inherit;
}

.ac-product-spotlight-layout { display: grid; grid-template-columns: minmax(0, .88fr) minmax(0, 1fr); column-gap: 32px; align-content: center; min-height: inherit; padding: clamp(24px, 4cqi, 48px); }
.ac-product-spotlight-copy { align-self: end; min-width: 0; }
.ac-product-spotlight-features { grid-column: 1; grid-row: 2; align-self: start; min-width: 0; }
.ac-product-spotlight-eyebrow { margin: 0 0 22px; font-size: 10px; line-height: 1.5; letter-spacing: .18em; text-transform: uppercase; }
.ac-product-spotlight-copy h2 { margin: 0; font-family: var(--serif, Georgia, serif); font-size: clamp(42px, 7.5cqi, 76px); font-weight: 400; letter-spacing: -.055em; line-height: 1.02; white-space: pre-line; text-wrap: balance; }
.ac-product-spotlight-description { max-width: 37ch; margin: 22px 0 0; color: var(--ac-spotlight-muted); font-size: 13px; line-height: 1.75; }
.ac-product-spotlight-list { display: grid; gap: 0; list-style: none; margin: 28px 0 0; padding: 0; border-top: 1px solid var(--ac-spotlight-line); }
.ac-product-spotlight-list li { margin: 0; padding: 0; border-bottom: 1px solid var(--ac-spotlight-line); }
.ac-product-spotlight-list button { display: flex; width: 100%; min-height: 66px; align-items: start; gap: 12px; padding: 14px 8px; border: 0; border-radius: 3px; background: transparent; color: inherit; text-align: left; font: inherit; cursor: pointer; transition: background 180ms ease; }
.ac-product-spotlight-number { width: 20px; flex-shrink: 0; color: var(--ac-spotlight-muted); font-size: 9px; line-height: 20px; }
.ac-product-spotlight-list strong { display: block; font-size: 12px; line-height: 20px; font-weight: 600; }
.ac-product-spotlight-list-detail { display: block; margin-top: 3px; color: var(--ac-spotlight-muted); font-size: 11px; line-height: 1.65; }
.ac-product-spotlight-list-arrow { margin-left: auto; font-size: 17px; line-height: 20px; }
.ac-product-spotlight-list button[aria-pressed="true"] { background: rgb(255 255 255 / 54%); }
.ac-product-spotlight-list button[aria-pressed="true"] .ac-product-spotlight-number { color: var(--ac-spotlight-accent); }
.ac-product-spotlight-action { display: flex; align-items: center; justify-content: space-between; width: fit-content; min-width: 174px; min-height: 48px; gap: 36px; margin-top: 26px; padding: 12px 19px; border: 1px solid var(--ac-spotlight-ink); border-radius: 99px; background: var(--ac-spotlight-ink); color: var(--ac-spotlight-surface); font-size: 12px; font-weight: 500; text-decoration: none; transition: background 180ms ease, color 180ms ease; }
.ac-product-spotlight-action span { font-size: 20px; line-height: 1; }
.ac-product-spotlight-visual { grid-column: 2; grid-row: 1 / span 2; min-width: 0; align-self: center; }
.ac-product-spotlight-image-area { position: relative; width: 100%; }
.ac-product-spotlight-image-area > img { display: block; width: 100%; height: auto; }
.ac-product-spotlight-points { position: absolute; inset: 0; }
.ac-product-spotlight-point { display: grid; position: absolute; z-index: 1; place-items: center; width: 44px; height: 44px; padding: 0; transform: translate(-50%, -50%); border: 0; border-radius: 50%; background: transparent; color: var(--ac-spotlight-ink); font: inherit; font-size: 10px; cursor: pointer; }
.ac-product-spotlight-point span { display: grid; place-items: center; width: 30px; height: 30px; border: 1px solid rgb(46 52 45 / 25%); border-radius: 50%; background: #f6f4eb; box-shadow: 0 2px 14px rgb(30 37 29 / 15%); transition: background 180ms ease, color 180ms ease, box-shadow 180ms ease; }
.ac-product-spotlight-point[aria-pressed="true"] span { border-color: var(--ac-spotlight-accent); background: var(--ac-spotlight-accent); color: #fff; box-shadow: 0 0 0 5px rgb(216 87 52 / 16%); }
.ac-product-spotlight-detail { display: flex; align-items: start; gap: 14px; min-height: 94px; padding: 18px 0 0; border-top: 1px solid var(--ac-spotlight-line); }
.ac-product-spotlight-detail-index { display: grid; flex-shrink: 0; place-items: center; width: 30px; height: 30px; border: 1px solid var(--ac-spotlight-line); border-radius: 50%; color: var(--ac-spotlight-muted); font-size: 10px; }
.ac-product-spotlight-detail strong { display: block; font-size: 12px; line-height: 1.7; }
.ac-product-spotlight-detail p { max-width: 43ch; margin: 4px 0 0; color: var(--ac-spotlight-muted); font-size: 11px; line-height: 1.75; }
.ac-product-spotlight-hero :is(button, a):focus-visible { outline: 2px solid var(--ac-spotlight-accent); outline-offset: 4px; }

@media (hover: hover) and (pointer: fine) {
  .ac-product-spotlight-list button:hover { background: rgb(255 255 255 / 40%); }
  .ac-product-spotlight-point:hover span { box-shadow: 0 0 0 5px rgb(246 244 235 / 35%); }
  .ac-product-spotlight-point[aria-pressed="true"]:hover span { box-shadow: 0 0 0 5px rgb(216 87 52 / 22%); }
  .ac-product-spotlight-action:hover { background: transparent; color: var(--ac-spotlight-ink); }
}

@container (max-width: 600px) {
  .ac-product-spotlight-layout { grid-template-columns: minmax(0, 1fr); gap: 28px; padding: 28px; }
  .ac-product-spotlight-copy,
  .ac-product-spotlight-visual,
  .ac-product-spotlight-features { grid-column: 1; grid-row: auto; }
  .ac-product-spotlight-features .ac-product-spotlight-list { margin-top: 0; }
  .ac-product-spotlight-copy h2 { font-size: clamp(42px, 11cqi, 66px); }
}

@media (prefers-reduced-motion: reduce) {
  .ac-product-spotlight-hero :is(button, a),
  .ac-product-spotlight-point span { transition: none; }
}
